import React, { useState, useEffect, useRef } from 'react';
import { Client, GSTProfile, Stakeholder, ConstitutionType, GstStatus, GstRegType, GstFilingFreq, ClientStatus, JurisdictionType } from '../../types';
import { mockBackend } from '../../services/mockBackend';

interface GSTClientFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  initialData?: Client | null;
}

const GSTClientFormModal: React.FC<GSTClientFormModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Client>>({
    legalName: '',
    tradeName: '',
    email: '',
    mobile: '',
    status: 'Active Filing',
    gstProfile: {
      gstin: '',
      username: '',
      password: '',
      gstStatus: 'Active',
      regDate: '',
      regType: 'Regular',
      filingFreq: 'Monthly',
      constitution: 'Proprietorship',
      stakeholders: [],
      address: '',
      jurisdictionType: 'State',
      sector: '',
      range: '',
      accountantName: '',
      accountantMobile: '',
    },
    bankDetails: {
      bankName: '',
      accountNo: '',
      ifsc: ''
    },
    remarks: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({
        legalName: '',
        tradeName: '',
        email: '',
        mobile: '',
        status: 'Active Filing',
        gstProfile: {
          gstin: '',
          username: '',
          password: '',
          gstStatus: 'Active',
          regDate: '',
          regType: 'Regular',
          filingFreq: 'Monthly',
          constitution: 'Proprietorship',
          stakeholders: [],
          address: '',
          jurisdictionType: 'State',
          sector: '',
          range: '',
          accountantName: '',
          accountantMobile: '',
        },
        bankDetails: { bankName: '', accountNo: '', ifsc: '' }
      });
    }
    setError(null);
  }, [initialData, isOpen]);

  useEffect(() => {
    const gstin = formData.gstProfile?.gstin || '';
    if (gstin.length >= 12) {
      const pan = gstin.substring(2, 12);
      if (formData.gstProfile?.constitution === 'Proprietorship') {
        const stakeholders = [{
          id: 'proprietor_1',
          name: formData.legalName || '',
          pan: pan,
          mobile: formData.mobile || ''
        }];
        setFormData(prev => ({
          ...prev,
          gstProfile: { ...prev.gstProfile!, stakeholders }
        }));
      }
    }
  }, [formData.gstProfile?.gstin, formData.gstProfile?.constitution, formData.legalName, formData.mobile]);

  const handleGstChange = (field: keyof GSTProfile, value: any) => {
    setFormData(prev => {
      const updatedProfile = { ...prev.gstProfile!, [field]: value };
      if (field === 'regType' && value === 'Composition') {
        updatedProfile.filingFreq = 'Quarterly';
      }
      return { ...prev, gstProfile: updatedProfile };
    });
  };

  const addStakeholder = () => {
    handleGstChange('stakeholders', [
      ...(formData.gstProfile?.stakeholders || []),
      { id: Date.now().toString(), name: '', mobile: '', pan: '' }
    ]);
  };

  const removeStakeholder = (id: string) => {
    handleGstChange('stakeholders', (formData.gstProfile?.stakeholders || []).filter(s => s.id !== id));
  };

  const updateStakeholder = (id: string, field: keyof Stakeholder, value: string) => {
    handleGstChange('stakeholders', (formData.gstProfile?.stakeholders || []).map(s => 
      s.id === id ? { ...s, [field]: value } : s
    ));
  };

  const validateGstin = (gst: string) => {
    const regex = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;
    return regex.test(gst);
  };

  const handleSave = async () => {
    try {
      if (!formData.gstProfile?.gstin || !validateGstin(formData.gstProfile.gstin)) {
        throw new Error("Invalid GSTIN Format");
      }
      if (!formData.legalName) throw new Error("Legal Name is required");

      const saved = await mockBackend.saveClient(formData);
      onSave(saved);
      onClose();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const base64String = event.target?.result as string;
        handleGstChange('certificateUrl', base64String);
      };
      reader.readAsDataURL(file);
    }
  };

  const copyAndLogin = () => {
    navigator.clipboard.writeText(formData.gstProfile?.username || '');
    window.open('https://services.gst.gov.in/services/login', '_blank');
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 overflow-hidden">
      <div className="w-full max-w-4xl bg-white rounded-[2rem] shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in zoom-in-95 duration-200">

        <div className="px-8 py-5 border-b border-slate-100 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-xl bg-indigo-600 flex items-center justify-center text-white shadow-lg">
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
            </div>
            <h2 className="text-xl font-black text-slate-900 tracking-tight uppercase">Add GST Client</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
            <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        {error && (
          <div className="mx-8 mt-4 p-4 bg-red-50 border border-red-200 rounded-xl text-red-600 font-bold text-sm">
            {error}
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">

          {/* Section: Basic Info */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Client Status</label>
              <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as ClientStatus})}>
                <option value="Active Filing">Active Filing</option>
                <option value="Case-by-Case">Case-by-Case</option>
                <option value="Inactive (Temporary)">Inactive (Temporary)</option>
              </select>
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Legal Name</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold uppercase"
                value={formData.legalName} onChange={e => setFormData({...formData, legalName: e.target.value})} placeholder="AS PER PAN" />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Trade Name</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                value={formData.tradeName} onChange={e => setFormData({...formData, tradeName: e.target.value})} placeholder="Business Name" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Mobile Number</label>
                <input type="tel" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.mobile} onChange={e => setFormData({...formData, mobile: e.target.value})} placeholder="Primary contact" />
              </div>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Email Address</label>
                <input type="email" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} placeholder="client@example.com" />
              </div>
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* Section: GST Credentials */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="md:col-span-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">GSTIN Identification</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-black uppercase tracking-widest text-lg"
                value={formData.gstProfile?.gstin} onChange={e => handleGstChange('gstin', e.target.value.toUpperCase())} placeholder="27XXXXX0000X1Z5" />
            </div>

            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Portal Username</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                value={formData.gstProfile?.username} onChange={e => handleGstChange('username', e.target.value)} />
            </div>

            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Portal Password</label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <input type={showPassword ? "text" : "password"} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                    value={formData.gstProfile?.password} onChange={e => handleGstChange('password', e.target.value)} />
                  <button onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-3 text-slate-400">
                    {showPassword ? <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg> : <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>}
                  </button>
                </div>
                <button onClick={copyAndLogin} className="px-4 bg-indigo-600 text-white font-black uppercase text-[10px] rounded-xl shadow-lg hover:bg-slate-900 transition-all flex items-center justify-center gap-2">
                  <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
                  Login
                </button>
              </div>
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* Section: Registration Status */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">GSTIN Status</label>
              <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                value={formData.gstProfile?.gstStatus} onChange={e => handleGstChange('gstStatus', e.target.value as GstStatus)}>
                <option value="Active">Active</option>
                <option value="Suspended">Suspended</option>
                <option value="Cancelled">Cancelled</option>
              </select>
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Reg. Date</label>
              <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                value={formData.gstProfile?.regDate} onChange={e => handleGstChange('regDate', e.target.value)} />
            </div>
            {formData.gstProfile?.gstStatus === 'Cancelled' && (
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Cancel Date</label>
                <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold text-red-600"
                  value={formData.gstProfile?.cancelDate} onChange={e => handleGstChange('cancelDate', e.target.value)} />
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Reg. Type</label>
              <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                value={formData.gstProfile?.regType} onChange={e => handleGstChange('regType', e.target.value as GstRegType)}>
                <option value="Regular">Regular</option>
                <option value="Composition">Composition</option>
              </select>
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Filing Freq</label>
              <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none disabled:opacity-50"
                disabled={formData.gstProfile?.regType === 'Composition'}
                value={formData.gstProfile?.filingFreq} onChange={e => handleGstChange('filingFreq', e.target.value as GstFilingFreq)}>
                <option value="Monthly">Monthly</option>
                <option value="Quarterly">Quarterly</option>
              </select>
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* Section: Constitution & Personnel */}
          <div className="space-y-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Constitution</label>
              <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                value={formData.gstProfile?.constitution} onChange={e => handleGstChange('constitution', e.target.value as ConstitutionType)}>
                <option value="Proprietorship">Proprietorship</option>
                <option value="Partnership">Partnership</option>
                <option value="HUF">HUF</option>
                <option value="Company">Company</option>
                <option value="Trust">Trust</option>
              </select>
            </div>

            <div className="bg-slate-50 rounded-2xl p-6 border border-slate-100 space-y-4">
              <div className="flex items-center justify-between">
                <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-500">Personnel Details</h4>
                {formData.gstProfile?.constitution !== 'Proprietorship' && (
                  <button onClick={addStakeholder} className="text-[9px] font-black uppercase bg-indigo-600 text-white px-3 py-1.5 rounded-lg shadow-sm">+ Add Personnel</button>
                )}
              </div>

              <div className="space-y-4">
                {(formData.gstProfile?.stakeholders || []).map((s) => (
                  <div key={s.id} className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end bg-white p-4 rounded-xl shadow-sm border border-slate-100 animate-in slide-in-from-left-2">
                    <div className="md:col-span-1">
                      <label className="text-[9px] font-black uppercase text-slate-400 mb-1 block">Name</label>
                      <input className="w-full border-slate-200 rounded-lg p-2 text-sm font-bold disabled:bg-slate-50 uppercase"
                        disabled={formData.gstProfile?.constitution === 'Proprietorship'}
                        value={s.name} onChange={e => updateStakeholder(s.id, 'name', e.target.value)} />
                    </div>
                    <div>
                      <label className="text-[9px] font-black uppercase text-slate-400 mb-1 block">PAN</label>
                      <input className="w-full border-slate-200 rounded-lg p-2 text-sm font-bold disabled:bg-slate-50 uppercase"
                        disabled={formData.gstProfile?.constitution === 'Proprietorship'}
                        value={s.pan} onChange={e => updateStakeholder(s.id, 'pan', e.target.value.toUpperCase())} />
                    </div>
                    <div>
                      <label className="text-[9px] font-black uppercase text-slate-400 mb-1 block">Mobile</label>
                      <input className="w-full border-slate-200 rounded-lg p-2 text-sm font-bold"
                        value={s.mobile} onChange={e => updateStakeholder(s.id, 'mobile', e.target.value)} />
                    </div>
                    {formData.gstProfile?.constitution !== 'Proprietorship' && (
                      <button onClick={() => removeStakeholder(s.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg">
                         <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                      </button>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* Section: Bank Details */}
          <div className="bg-slate-50 rounded-2xl p-6 border border-slate-100">
            <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-4">Bank Information</h4>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Bank Name</label>
                <input className="w-full bg-white border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.bankDetails?.bankName} onChange={e => setFormData({...formData, bankDetails: {...formData.bankDetails!, bankName: e.target.value}})} />
              </div>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Account Number</label>
                <input className="w-full bg-white border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.bankDetails?.accountNo} onChange={e => setFormData({...formData, bankDetails: {...formData.bankDetails!, accountNo: e.target.value}})} />
              </div>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">IFSC Code</label>
                <input className="w-full bg-white border border-slate-200 rounded-xl p-3 font-bold uppercase"
                  value={formData.bankDetails?.ifsc} onChange={e => setFormData({...formData, bankDetails: {...formData.bankDetails!, ifsc: e.target.value.toUpperCase()}})} />
              </div>
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* Section: Accountant Details */}
          <div className="bg-slate-50 rounded-2xl p-6 border border-slate-100">
            <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-4">Accountant Contact</h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Accountant Name</label>
                <input className="w-full bg-white border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.gstProfile?.accountantName} onChange={e => handleGstChange('accountantName', e.target.value)} />
              </div>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Accountant Mobile</label>
                <input type="tel" className="w-full bg-white border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.gstProfile?.accountantMobile} onChange={e => handleGstChange('accountantMobile', e.target.value)} />
              </div>
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* Section: Document & Remarks */}
          <div className="space-y-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">GST Certificate (PDF)</label>
              <div className="flex items-center gap-3 bg-slate-50 border border-slate-200 rounded-xl p-3 group hover:border-indigo-300 transition-colors cursor-pointer"
                   onClick={() => fileInputRef.current?.click()}>
                 <div className="h-10 w-10 rounded-lg bg-white border border-slate-200 flex items-center justify-center text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white transition-all shadow-sm">
                    <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                 </div>
                 <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileUpload} />
                 <span className="text-xs font-bold text-slate-500 truncate max-w-[300px]">
                    {formData.gstProfile?.certificateUrl?.startsWith('data:') ? 'Document Ready for Vault' : (formData.gstProfile?.certificateUrl || 'Click to upload PDF')}
                 </span>
              </div>
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Address</label>
              <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold h-24"
                value={formData.gstProfile?.address} onChange={e => handleGstChange('address', e.target.value)} />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Remarks</label>
              <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold h-24"
                value={formData.remarks} onChange={e => setFormData({...formData, remarks: e.target.value})} />
            </div>
          </div>
        </div>

        <div className="p-8 border-t border-slate-100 flex gap-4 bg-slate-50/50">
          <button onClick={onClose} className="flex-1 py-4 rounded-xl text-slate-500 font-black uppercase text-[10px] border border-slate-200">Discard</button>
          <button onClick={handleSave} className="flex-[2] bg-indigo-600 text-white font-black uppercase text-[10px] py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all">
            {initialData ? 'Update Entity' : 'Save New GST Client'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default GSTClientFormModal;

import React, { useState, useEffect, useMemo } from 'react';
import { Client, JurisdictionType } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import Loader from '../../components/Loader';

interface GstMasterPortfolioProps {
  externalSearch?: string;
  hideInternalSearch?: boolean;
  jurisdictionFilter?: JurisdictionType | 'All';
  sectorFilter?: string;
  rangeFilter?: string;
}

const GstMasterPortfolio: React.FC<GstMasterPortfolioProps> = ({ 
  externalSearch = '', 
  hideInternalSearch = false,
  jurisdictionFilter = 'All',
  sectorFilter = 'All',
  rangeFilter = 'All'
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');

  const [isGstModalOpen, setIsGstModalOpen] = useState(false);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [activeMenuId, setActiveMenuId] = useState<string | null>(null);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const [tempPassword, setTempPassword] = useState('');
  const [showPassInView, setShowPassInView] = useState(false);
  const [isEditingPassword, setIsEditingPassword] = useState(false);
  const [localPassValue, setLocalPassValue] = useState('');
  const [showPassInLogin, setShowPassInLogin] = useState(false);

  const [gstStatusColFilter, setGstStatusColFilter] = useState<string>('All');
  const [clientStatusColFilter, setClientStatusColFilter] = useState<string>('All');

  const [openFilterCol, setOpenFilterCol] = useState<'gst' | 'status' | null>(null);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.gstProfile) || []);
    } catch (error) {
      console.error("Failed to fetch clients", error);
      setClients([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return 'N/A';
    if (!dateStr.includes('-')) return dateStr;
    const parts = dateStr.split('-');
    if (parts[0].length === 4) { // YYYY-MM-DD to DD-MM-YYYY
      return `${parts[2]}-${parts[1]}-${parts[0]}`;
    }
    return dateStr;
  };

  const filteredClients = useMemo(() => {
    let list = Array.isArray(clients) ? clients : [];

    if (jurisdictionFilter !== 'All') {
      list = list.filter(c => c.gstProfile?.jurisdictionType === jurisdictionFilter);
      if (jurisdictionFilter === 'State' && sectorFilter !== 'All') {
        list = list.filter(c => c.gstProfile?.sector === sectorFilter);
      }
      if (jurisdictionFilter === 'Center' && rangeFilter !== 'All') {
        list = list.filter(c => c.gstProfile?.range === rangeFilter);
      }
    }

    if (gstStatusColFilter !== 'All') {
      list = list.filter(c => c.gstProfile?.gstStatus === gstStatusColFilter);
    }
    if (clientStatusColFilter !== 'All') {
      list = list.filter(c => c.status === clientStatusColFilter);
    }

    const s = (externalSearch || search || '').toLowerCase();
    return list.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin && c.gstProfile.gstin.toLowerCase().includes(s)) || 
      (c.mobile || '').includes(s)
    );
  }, [clients, search, externalSearch, jurisdictionFilter, sectorFilter, rangeFilter, gstStatusColFilter, clientStatusColFilter]);

  const handleEdit = (client: Client) => {
    setSelectedClient(client);
    setIsGstModalOpen(true);
    setIsDetailModalOpen(false);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Are you sure you want to delete this client record?')) {
      await mockBackend.deleteClient(id);
      setIsDetailModalOpen(false);
      fetchClients();
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const shareViaWhatsApp = (text: string) => {
    const url = `https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`;
    window.open(url, '_blank');
  };

  const handleFileShare = async (client: Client) => {
    const dataUrl = client.gstProfile?.certificateUrl;
    const title = `${client.tradeName || client.legalName} GST Certificate`;
    const text = getCertText(client);

    if (dataUrl && dataUrl.startsWith('data:application/pdf')) {
      try {
        const res = await fetch(dataUrl);
        const blob = await res.blob();
        const file = new File([blob], `${client.gstProfile?.gstin || 'GST'}_Certificate.pdf`, { type: 'application/pdf' });

        if (navigator.canShare && navigator.canShare({ files: [file] })) {
          await navigator.share({
            files: [file],
            title: title,
            text: text
          });
          return;
        }
      } catch (err) {
        console.warn('File share failed, falling back to WhatsApp/Download', err);
      }

      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = `${client.gstProfile?.gstin}_Certificate.pdf`;
      link.click();

      // After initiating download, also share text on WhatsApp if user specifically wants WhatsApp
      shareViaWhatsApp(text + "\n\n(Document shared via separate direct download)");
    } else {
      if (navigator.share) {
        await navigator.share({ title, text });
      } else {
        shareViaWhatsApp(text);
      }
    }
  };

  const openPortalLogin = async (client: Client, finalPass?: string) => {
    // If a password was changed in the gateway modal, sync it first
    if (finalPass && finalPass !== client.gstProfile?.password) {
      const updatedClient = {
        ...client,
        gstProfile: { ...client.gstProfile!, password: finalPass }
      };
      await mockBackend.saveClient(updatedClient);
      fetchClients();
    }
    copyToClipboard(client.gstProfile?.username || '');
    window.open('https://services.gst.gov.in/services/login', '_blank');
  };

  const openPortalSearch = (gstin: string) => {
    copyToClipboard(gstin);
    window.open('https://services.gst.gov.in/services/searchtp', '_blank');
  };

  const saveQuickPassword = async () => {
    if (!selectedClient) return;
    const updatedClient = {
      ...selectedClient,
      gstProfile: {
        ...selectedClient.gstProfile!,
        password: localPassValue
      }
    };
    await mockBackend.saveClient(updatedClient);
    setSelectedClient(updatedClient);
    setIsEditingPassword(false);
    fetchClients();
  };

  const getCredText = (client: Client) => {
    return `*GST Credentials for ${client.tradeName || client.legalName}*\n\n*GSTIN:* ${client.gstProfile?.gstin}\n*Username:* ${client.gstProfile?.username}\n*Password:* ${client.gstProfile?.password}\n\n_Shared via Clientify_`;
  };

  const getCertText = (client: Client) => {
    return `*GST Registration Details: ${client.tradeName || client.legalName}*\n\n*GSTIN:* ${client.gstProfile?.gstin}\n*Status:* ${client.gstProfile?.gstStatus}\n*Reg Date:* ${formatDate(client.gstProfile?.regDate)}\n\n_Shared via Clientify_`;
  };

  const getFullShareText = (client: Client) => {
    const stakeholders = client.gstProfile?.stakeholders?.map(s => `• ${s.name} (${s.pan})`).join('\n') || 'None';
    return `*Clientify: Master Profile Share*\n\n*Trade Name:* ${client.tradeName}\n*Legal Name:* ${client.legalName}\n*GSTIN:* ${client.gstProfile?.gstin}\n*Mobile:* ${client.mobile}\n*Email:* ${client.email}\n\n*Login Credentials:*\n*Username:* ${client.gstProfile?.username}\n*Password:* ${client.gstProfile?.password}\n\n*Personnel:*\n${stakeholders}`;
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-auto">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap">S.No.</th>
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Trade Name</th>
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Legal Name</th>
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap">Mobile No.</th>
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap">GSTIN</th>

                <th className="px-4 py-5 text-center relative">
                  <div className="flex items-center justify-center gap-1.5">
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">GST Status</span>
                    <button onClick={() => setOpenFilterCol(openFilterCol === 'gst' ? null : 'gst')} className={`h-6 w-6 rounded-md flex items-center justify-center transition-colors ${gstStatusColFilter !== 'All' ? 'bg-indigo-100 text-indigo-600' : 'text-slate-400 hover:bg-slate-200'}`}>
                       <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {openFilterCol === 'gst' && (
                    <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1.5 animate-in zoom-in-95">
                      {['All', 'Active', 'Suspended', 'Cancelled'].map(opt => (
                        <button key={opt} onClick={() => { setGstStatusColFilter(opt); setOpenFilterCol(null); }} className={`w-full text-left px-3 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-lg ${gstStatusColFilter === opt ? 'bg-indigo-600 text-white' : 'text-slate-600 hover:bg-slate-50'}`}>{opt}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-center relative">
                  <div className="flex items-center justify-center gap-1.5">
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Status</span>
                    <button onClick={() => setOpenFilterCol(openFilterCol === 'status' ? null : 'status')} className={`h-6 w-6 rounded-md flex items-center justify-center transition-colors ${clientStatusColFilter !== 'All' ? 'bg-indigo-100 text-indigo-600' : 'text-slate-400 hover:bg-slate-200'}`}>
                       <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {openFilterCol === 'status' && (
                    <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1.5 animate-in zoom-in-95">
                      {['All', 'Active Filing', 'Case-by-Case', 'Inactive (Temporary)'].map(opt => (
                        <button key={opt} onClick={() => { setClientStatusColFilter(opt); setOpenFilterCol(null); }} className={`w-full text-left px-3 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-lg ${clientStatusColFilter === opt ? 'bg-indigo-600 text-white' : 'text-slate-600 hover:bg-slate-50'}`}>{opt === 'Active Filing' ? 'Active' : opt === 'Case-by-Case' ? 'Case' : opt === 'Inactive (Temporary)' ? 'Inact' : 'All'}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right min-w-[100px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredClients.length === 0 ? (
                <tr>
                  <td colSpan={8} className="py-20 text-center text-slate-400 font-bold uppercase tracking-widest text-xs">No records found</td>
                </tr>
              ) : (
                filteredClients.map((client, idx) => (
                  <tr key={client.id} className={`transition-all duration-300 group ${idx % 2 === 0 ? 'bg-white' : 'bg-slate-50/60 hover:bg-indigo-50/40'}`}>
                    <td className="px-4 py-5">
                      <span className="text-xs font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</span>
                    </td>
                    <td className="px-4 py-5">
                      <p className="text-sm font-black text-slate-900 leading-tight truncate max-w-[160px]">{client.tradeName || '---'}</p>
                    </td>
                    <td className="px-4 py-5">
                      <p className="text-xs font-bold text-slate-500 uppercase truncate max-w-[160px]">{client.legalName}</p>
                    </td>
                    <td className="px-4 py-5 whitespace-nowrap">
                      <p className="text-xs font-black text-slate-700">{client.mobile || '---'}</p>
                    </td>
                    <td className="px-4 py-5 whitespace-nowrap">
                       <div className="flex items-center gap-2">
                         <span className="text-[11px] font-black text-indigo-600 font-mono tracking-widest">{client.gstProfile?.gstin}</span>
                         <button 
                           onClick={() => { copyToClipboard(client.gstProfile?.gstin || ''); openPortalSearch(client.gstProfile?.gstin || ''); }}
                           className="h-6 w-6 rounded bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white transition-all shadow-sm flex items-center justify-center opacity-0 group-hover:opacity-100"
                           title="Search & Copy GSTIN"
                         >
                           <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                         </button>
                       </div>
                    </td>
                    <td className="px-4 py-5 text-center whitespace-nowrap">
                      <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider ${
                        client.gstProfile?.gstStatus === 'Active' ? 'bg-green-100 text-green-700' : 
                        client.gstProfile?.gstStatus === 'Suspended' ? 'bg-amber-100 text-amber-700' : 'bg-red-100 text-red-700'
                      }`}>
                        {client.gstProfile?.gstStatus || 'N/A'}
                      </span>
                    </td>
                    <td className="px-4 py-5 text-center whitespace-nowrap">
                      <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider ${
                        client.status === 'Active Filing' ? 'bg-blue-100 text-blue-700' : 
                        client.status === 'Case-by-Case' ? 'bg-purple-100 text-purple-700' : 'bg-slate-100 text-slate-600'
                      }`}>
                        {client.status}
                      </span>
                    </td>
                    <td className="px-4 py-5 text-right whitespace-nowrap">
                      <div className="flex items-center justify-end gap-2 relative">
                        <button 
                          onClick={() => { setSelectedClient(client); setIsDetailModalOpen(true); setShowPassInView(false); setIsEditingPassword(false); setLocalPassValue(client.gstProfile?.password || ''); }}
                          className="h-8 w-8 rounded-lg bg-white border border-slate-200 text-slate-400 hover:text-indigo-600 hover:border-indigo-200 shadow-sm flex items-center justify-center transition-all"
                          title="View Details"
                        >
                          <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                        </button>

                        <div className="relative">
                          <button 
                            onClick={() => setActiveMenuId(activeMenuId === client.id ? null : client.id)}
                            className="h-8 w-8 rounded-lg bg-white border border-slate-200 text-slate-400 hover:text-slate-900 hover:border-slate-300 shadow-sm flex items-center justify-center transition-all"
                          >
                            <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z" /></svg>
                          </button>

                          {activeMenuId === client.id && (
                            <>
                              <div className="fixed inset-0 z-40" onClick={() => setActiveMenuId(null)} />
                              <div className="absolute right-0 mt-2 w-64 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 p-1.5 animate-in zoom-in-95 overflow-hidden">
                                <button 
                                  onClick={() => { setSelectedClient(client); setTempPassword(client.gstProfile?.password || ''); setIsLoginModalOpen(true); setActiveMenuId(null); }}
                                  className="w-full flex items-center gap-3 px-3 py-2.5 text-xs font-black uppercase tracking-widest text-slate-600 hover:bg-indigo-50 hover:text-indigo-600 rounded-xl transition-colors"
                                >
                                  <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
                                  Login Gateway
                                </button>

                                <div className="h-px bg-slate-100 my-1" />
                                <div className="px-3 py-1 text-[9px] font-black uppercase text-slate-400 tracking-widest">Share Details</div>

                                <button 
                                  onClick={() => { shareViaWhatsApp(getCredText(client)); setActiveMenuId(null); }}
                                  className="w-full flex items-center gap-3 px-3 py-2.5 text-xs font-black uppercase tracking-widest text-slate-600 hover:bg-emerald-50 hover:text-emerald-600 rounded-xl transition-colors"
                                >
                                  <svg className="h-4 w-4 text-emerald-600" fill="currentColor" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L0 24l6.335-1.662c1.72.94 3.659 1.437 5.634 1.437h.005c6.558 0 11.894-5.335 11.897-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
                                  WhatsApp Credentials
                                </button>
                                <button 
                                  onClick={() => { handleFileShare(client); setActiveMenuId(null); }}
                                  className="w-full flex items-center gap-3 px-3 py-2.5 text-xs font-black uppercase tracking-widest text-slate-600 hover:bg-indigo-50 hover:text-indigo-600 rounded-xl transition-colors"
                                >
                                  <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                  Share Document (PDF)
                                </button>
                              </div>
                            </>
                          )}
                        </div>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      <GSTClientFormModal isOpen={isGstModalOpen} onClose={() => setIsGstModalOpen(false)} onSave={() => fetchClients()} initialData={selectedClient} />

      {/* COMPREHENSIVE VIEW DETAILS MODAL */}
      {isDetailModalOpen && selectedClient && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
          <div className="w-full max-w-5xl max-h-[95vh] bg-white rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <div className="px-6 md:px-10 py-6 md:py-8 bg-slate-50 border-b border-slate-100 flex items-center justify-between shrink-0">
              <div className="min-w-0">
                 <h2 className="text-xl md:text-2xl font-black text-slate-900 tracking-tight leading-none uppercase truncate">
                   {selectedClient.tradeName || selectedClient.legalName}
                 </h2>
                 <p className="text-xs md:text-sm font-bold text-slate-500 mt-2 uppercase tracking-widest truncate">
                   {selectedClient.tradeName ? selectedClient.legalName : 'Principal Legal Identity Registered'}
                 </p>
              </div>
              <div className="flex items-center gap-2 md:gap-3 shrink-0">
                <button onClick={() => handleDelete(selectedClient.id)} className="h-9 md:h-10 px-4 md:px-6 bg-white border border-red-100 text-red-600 rounded-xl font-black text-[9px] md:text-[10px] uppercase tracking-widest hover:bg-red-50 transition-all">Delete</button>
                <button onClick={() => handleEdit(selectedClient)} className="h-9 md:h-10 px-6 md:px-8 bg-indigo-600 text-white rounded-xl font-black text-[9px] md:text-[10px] uppercase tracking-widest shadow-lg shadow-indigo-100 hover:bg-slate-900 transition-all">Edit</button>
                <button onClick={() => setIsDetailModalOpen(false)} className="h-9 md:h-10 w-9 md:w-10 flex items-center justify-center rounded-xl hover:bg-slate-200 transition-colors">
                  <svg className="h-5 md:h-6 w-5 md:w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            </div>

            <div className="p-6 md:p-10 overflow-y-auto no-scrollbar flex-1 space-y-8 md:space-y-12">
               {/* Section: Business Profile */}
               <section>
                  <h4 className="text-[10px] md:text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6 flex items-center gap-3">
                    Business Profile <div className="h-px flex-1 bg-slate-100" />
                  </h4>
                  <div className="grid grid-cols-1 md:grid-cols-4 gap-6 md:gap-8">
                     <div className="space-y-1 col-span-1 md:col-span-2">
                        <p className="text-[9px] font-black uppercase text-slate-400 mb-1">GSTIN Identification</p>
                        <div className="flex items-center gap-2 group">
