import React, { useState, useEffect } from 'react';
import { Client, ClientService, ClientStatus, ITProfile } from '../../types';
import { mockBackend } from '../../services/mockBackend';

interface ITClientFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  initialData?: Client | null;
}

const SERVICES: ClientService[] = ['IT Return', 'Audit', 'Notice handling', 'MSME', 'Food License'];

const ITClientFormModal: React.FC<ITClientFormModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [mergeAlert, setMergeAlert] = useState<Client | null>(null);

  const [formData, setFormData] = useState<Partial<Client>>({
    legalName: '',
    tradeName: '',
    email: '',
    mobile: '',
    status: 'Active Filing',
    itProfile: {
      pan: '',
      category: 'Individual',
      username: '',
      password: '',
    },
    bankDetails: {
      bankName: '',
      accountNo: '',
      ifsc: ''
    },
    services: ['IT Return'],
    remarks: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({
        legalName: '',
        tradeName: '',
        email: '',
        mobile: '',
        status: 'Active Filing',
        itProfile: {
          pan: '',
          category: 'Individual',
          username: '',
          password: '',
        },
        bankDetails: { bankName: '', accountNo: '', ifsc: '' },
        services: ['IT Return'],
        remarks: ''
      });
    }
    setError(null);
    setMergeAlert(null);
  }, [initialData, isOpen]);

  const handleItChange = (field: keyof ITProfile, value: any) => {
    setFormData(prev => ({
      ...prev,
      itProfile: { ...prev.itProfile!, [field]: value }
    }));
  };

  const validatePan = async (val: string) => {
    const pan = val.toUpperCase().slice(0, 10);
    handleItChange('pan', pan);
    if (pan.length === 10) {
      const conflict = await mockBackend.checkPanConflict(pan, initialData?.id);
      if (conflict) setMergeAlert(conflict);
      else setMergeAlert(null);
    } else {
      setMergeAlert(null);
    }
  };

  const handleSave = async () => {
    try {
      if (!formData.legalName) throw new Error("Legal Name is required");
      if (!formData.itProfile?.pan || formData.itProfile.pan.length < 10) {
        throw new Error("Valid 10-digit PAN is required");
      }

      const saved = await mockBackend.saveClient(formData);
      onSave(saved);
      onClose();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const copyAndLogin = () => {
    navigator.clipboard.writeText(formData.itProfile?.username || '');
    window.open('https://www.incometax.gov.in/iec/foportal/', '_blank');
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 overflow-hidden">
      <div className="w-full max-w-4xl bg-white rounded-[2rem] shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="px-8 py-5 border-b border-slate-100 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-xl bg-emerald-600 flex items-center justify-center text-white shadow-lg">
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
            </div>
            <h2 className="text-xl font-black text-slate-900 tracking-tight uppercase">Add IT Client</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
            <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        {error && (
          <div className="mx-8 mt-4 p-4 bg-red-50 border border-red-200 rounded-xl text-red-600 font-bold text-sm">
            {error}
          </div>
        )}

        {mergeAlert && (
          <div className="mx-8 mt-4 p-4 bg-amber-50 border border-amber-200 rounded-xl flex items-center gap-3">
            <svg className="h-5 w-5 text-amber-600 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
            <p className="text-amber-800 text-xs font-bold">PAN conflict: Already assigned to <span className="underline">{mergeAlert.legalName}</span></p>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">

          {/* Section: Basic Info */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Entity Status</label>
              <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as ClientStatus})}>
                <option value="Active Filing">Active Filing</option>
                <option value="Case-by-Case">Case-by-Case</option>
                <option value="Inactive (Temporary)">Inactive (Temporary)</option>
                <option value="Inactive (Closed)">Inactive (Closed)</option>
              </select>
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Legal Name</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold uppercase"
                value={formData.legalName} onChange={e => setFormData({...formData, legalName: e.target.value})} placeholder="AS PER PAN CARD" />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Trade/Firm Name</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                value={formData.tradeName} onChange={e => setFormData({...formData, tradeName: e.target.value})} placeholder="Practice or Shop Name" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Mobile Number</label>
                <input type="tel" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.mobile} onChange={e => setFormData({...formData, mobile: e.target.value})} placeholder="10-digit primary" />
              </div>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Email Address</label>
                <input type="email" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} placeholder="client@example.com" />
              </div>
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* Section: IT Credentials */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="md:col-span-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">PAN Identifier</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-black uppercase tracking-[0.3em] text-lg text-emerald-600"
