import React, { useState, useEffect, useMemo } from 'react';
import { Client, GstFilingFreq } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';

const YEARS = ['2023-24', '2024-25', '2025-26'];
const MONTHS = [
  'April', 'May', 'June', 'July', 'August', 'September', 
  'October', 'November', 'December', 'January', 'February', 'March'
];

const MonthlyFiling: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState('2024-25');
  const [selectedMonth, setSelectedMonth] = useState(MONTHS[new Date().getMonth()]);

  // Track status locally for the demo - in production this would come from a 'filings' collection
  const [filingStatuses, setFilingStatuses] = useState<Record<string, { r1: boolean; r3b: boolean }>>({});

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      // Filter only Monthly filers
      const monthlyFilers = data.filter(c => c.gstProfile?.filingFreq === 'Monthly');
      setClients(monthlyFilers);

      // Initialize some dummy statuses if not present
      const initialStatuses: any = {};
      monthlyFilers.forEach(c => {
        initialStatuses[c.id] = { r1: false, r3b: false };
      });
      setFilingStatuses(initialStatuses);
    } catch (error) {
      console.error("Failed to fetch monthly filers", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const toggleStatus = (clientId: string, type: 'r1' | 'r3b') => {
    setFilingStatuses(prev => ({
      ...prev,
      [clientId]: {
        ...prev[clientId],
        [type]: !prev[clientId][type]
      }
    }));
  };

  const filteredClients = useMemo(() => {
    const s = search.toLowerCase();
    return clients.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin || '').toLowerCase().includes(s)
    );
  }, [clients, search]);

  const stats = useMemo(() => {
    const total = filteredClients.length;
    const r1Filed = filteredClients.filter(c => filingStatuses[c.id]?.r1).length;
    const r3bFiled = filteredClients.filter(c => filingStatuses[c.id]?.r3b).length;
    return { total, r1Filed, r3bFiled };
  }, [filteredClients, filingStatuses]);

  const handleExport = () => {
    const headers = ["Trade Name", "GSTIN", `GSTR-1 (${selectedMonth})`, `GSTR-3B (${selectedMonth})`].join(",");
    const rows = filteredClients.map(c => {
      const status = filingStatuses[c.id];
      return [
        c.tradeName || c.legalName,
        c.gstProfile?.gstin,
        status?.r1 ? "FILED" : "PENDING",
        status?.r3b ? "FILED" : "PENDING"
      ].join(",");
    }).join("\n");

    const blob = new Blob([headers + "\n" + rows], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Monthly_Filing_${selectedMonth}_${selectedYear}.csv`;
    link.click();
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500">

      {/* High-End Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">

        {/* Compliance Stats */}
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Monthly Clients</p>
            <p className="text-xl font-black text-slate-900 leading-none">{stats.total}</p>
          </div>
          <div className="text-center">
            <p className="text-[9px] font-black text-emerald-500 uppercase tracking-widest mb-1">GSTR-1 Filed</p>
            <p className="text-xl font-black text-emerald-600 leading-none">{stats.r1Filed}</p>
          </div>
          <div className="text-center">
            <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mb-1">GSTR-3B Filed</p>
            <p className="text-xl font-black text-indigo-600 leading-none">{stats.r3bFiled}</p>
          </div>
        </div>

        {/* Search */}
        <div className="relative flex-1 w-full group">
          <input 
            type="text" 
            placeholder="Filter by trade name or GSTIN..." 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-2xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-emerald-600/10 transition-all outline-none"
          />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-emerald-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
        </div>

        {/* Period Selectors */}
        <div className="flex items-center gap-2 shrink-0">
          <select 
            value={selectedYear} 
            onChange={(e) => setSelectedYear(e.target.value)}
            className="bg-slate-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-emerald-600/10 outline-none cursor-pointer"
          >
            {YEARS.map(y => <option key={y} value={y}>{y}</option>)}
          </select>
          <select 
            value={selectedMonth} 
            onChange={(e) => setSelectedMonth(e.target.value)}
            className="bg-slate-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-emerald-600/10 outline-none cursor-pointer"
          >
            {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
        </div>

        {/* Action Button */}
        <button 
          onClick={handleExport}
          className="h-12 px-6 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-emerald-600 transition-all flex items-center gap-2 shrink-0 ml-auto lg:ml-0"
        >
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
          </svg>
          Export Status
        </button>
      </div>

      {/* Main Table Content */}
      <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-auto min-w-[900px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">S.No.</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Trading Identity</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">GSTIN Identifier</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-center">GSTR-1 Status</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-center">GSTR-3B Status</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredClients.length === 0 ? (
                <tr>
                  <td colSpan={6} className="py-24 text-center">
                    <p className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-300">No monthly filers identified</p>
                  </td>
                </tr>
              ) : (
                filteredClients.map((client, idx) => {
                  const status = filingStatuses[client.id] || { r1: false, r3b: false };
                  return (
                    <tr key={client.id} className="group hover:bg-slate-50/50 transition-colors">
                      <td className="px-6 py-5">
                        <span className="text-xs font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</span>
                      </td>
                      <td className="px-6 py-5">
                        <p className="text-sm font-black text-slate-900 leading-tight uppercase truncate max-w-[200px]">
                          {client.tradeName || client.legalName}
                        </p>
                      </td>
                      <td className="px-6 py-5">
                         <span className="text-[11px] font-black text-indigo-600 font-mono tracking-widest uppercase">{client.gstProfile?.gstin}</span>
                      </td>
                      <td className="px-6 py-5 text-center">
                        <button 
                          onClick={() => toggleStatus(client.id, 'r1')}
                          className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${
                            status.r1 ? 'bg-emerald-100 text-emerald-700 shadow-sm' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'
                          }`}
                        >
                          {status.r1 ? '✓ Filed' : 'Pending'}
                        </button>
                      </td>
                      <td className="px-6 py-5 text-center">
                        <button 
                          onClick={() => toggleStatus(client.id, 'r3b')}
                          className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${
                            status.r3b ? 'bg-indigo-100 text-indigo-700 shadow-sm' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'
                          }`}
                        >
                          {status.r3b ? '✓ Filed' : 'Pending'}
                        </button>
                      </td>
                      <td className="px-6 py-5 text-right">
                         <button 
                           onClick={() => window.open('https://services.gst.gov.in/services/login', '_blank')}
                           className="h-9 w-9 rounded-xl bg-white border border-slate-200 text-slate-400 hover:text-indigo-600 hover:border-indigo-200 shadow-sm flex items-center justify-center transition-all ml-auto"
