import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';

const YEARS = ['2023-24', '2024-25', '2025-26'];
const MONTHS = [
  'April', 'May', 'June', 'July', 'August', 'September', 
  'October', 'November', 'December', 'January', 'February', 'March'
];

const MonthlyFiling: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState('2024-25');
  const [selectedMonth, setSelectedMonth] = useState(MONTHS[new Date().getMonth()]);

  // Inline editing states
  const [editingPasswordId, setEditingPasswordId] = useState<string | null>(null);
  const [tempPassword, setTempPassword] = useState('');
  const [visiblePasswords, setVisiblePasswords] = useState<Set<string>>(new Set());

  // Track filing status locally (Mock)
  const [filingStatuses, setFilingStatuses] = useState<Record<string, { r1: boolean; r3b: boolean }>>({});

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      const monthlyFilers = data.filter(c => c.gstProfile?.filingFreq === 'Monthly');
      setClients(monthlyFilers);

      const initialStatuses: any = {};
      monthlyFilers.forEach(c => {
        initialStatuses[c.id] = { r1: false, r3b: false };
      });
      setFilingStatuses(initialStatuses);
    } catch (error) {
      console.error("Failed to fetch monthly filers", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const toggleStatus = (clientId: string, type: 'r1' | 'r3b') => {
    setFilingStatuses(prev => ({
      ...prev,
      [clientId]: { ...prev[clientId], [type]: !prev[clientId][type] }
    }));
  };

  const togglePasswordVisibility = (clientId: string) => {
    setVisiblePasswords(prev => {
      const next = new Set(prev);
      if (next.has(clientId)) next.delete(clientId);
      else next.add(clientId);
      return next;
    });
  };

  const startEditingPassword = (client: Client) => {
    setEditingPasswordId(client.id);
    setTempPassword(client.gstProfile?.password || '');
  };

  const savePassword = async (client: Client) => {
    try {
      const updatedClient = {
        ...client,
        gstProfile: { ...client.gstProfile!, password: tempPassword }
      };
      await mockBackend.saveClient(updatedClient);
      setClients(prev => prev.map(c => c.id === client.id ? (updatedClient as Client) : c));
      setEditingPasswordId(null);
    } catch (err) {
      alert("Failed to update password");
    }
  };

  const openPortalSearch = (gstin: string) => {
    navigator.clipboard.writeText(gstin);
    window.open('https://services.gst.gov.in/services/searchtp', '_blank');
