  const handleExport = () => {
    const headers = ["S.No", "Trade Name", "Legal Name", "GSTIN", "ID", "Password", `GSTR-1 (${selectedMonth})`, `GSTR-3B (${selectedMonth})`].join(",");
    const rows = filteredClients.map((c, idx) => {
      const status = filingStatuses[c.id];
      return [
        idx + 1,
        c.tradeName || "---",
        c.legalName,
        c.gstProfile?.gstin,
        c.gstProfile?.username,
        c.gstProfile?.password,
        status?.r1 ? "FILED" : "PENDING",
        status?.r3b ? "FILED" : "PENDING"
      ].join(",");
    }).join("\n");

    const blob = new Blob([headers + "\n" + rows], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Monthly_Filing_Report_${selectedMonth}_${selectedYear}.csv`;
    link.click();
