import { useState, useEffect } from 'react';

export interface FilingStatus {
  r1: boolean;
  r3b: boolean;
}

// Global storage key for compliance tracking
const STORAGE_KEY = 'clientify_filing_master_data';

export const useMonthlyFilingLogic = (selectedYear: string, selectedMonth: string) => {
  // Period Key example: "2024-25_April"
  const periodKey = `${selectedYear}_${selectedMonth}`;

  const [allFilingData, setAllFilingData] = useState<Record<string, Record<string, FilingStatus>>>({});

  // Initialize from LocalStorage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        setAllFilingData(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse filing data", e);
      }
    }
  }, []);

  // Get statuses for the current period
  const currentPeriodData = allFilingData[periodKey] || {};

  const toggleStatus = (clientId: string, type: 'r1' | 'r3b') => {
    setAllFilingData(prev => {
      const periodData = prev[periodKey] || {};
      const clientData = periodData[clientId] || { r1: false, r3b: false };

      const nextData = {
        ...prev,
        [periodKey]: {
          ...periodData,
          [clientId]: {
            ...clientData,
            [type]: !clientData[type]
          }
        }
      };

      localStorage.setItem(STORAGE_KEY, JSON.stringify(nextData));
      return nextData;
    });
  };

  const getStatus = (clientId: string): FilingStatus => {
    return currentPeriodData[clientId] || { r1: false, r3b: false };
  };

  return {
    getStatus,
    toggleStatus,
    currentPeriodData
  };
};

