import GSTClientFormModal from '../../Clientform/GSTClientFormModal';
import Loader from '../../../components/Loader';
import { useMonthlyFilingLogic } from './filinglogic/MonthlyFilingLogic';

const YEARS = ['2023-24', '2024-25', '2025-26'];
const MONTHS = [
  'April', 'May', 'June', 'July', 'August', 'September', 
  'October', 'November', 'December', 'January', 'February', 'March'
];

const MonthlyFiling: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState('2024-25');
  const [selectedMonth, setSelectedMonth] = useState(MONTHS[new Date().getMonth()]);

  // Header Filters
  const [r1Filter, setR1Filter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [r3bFilter, setR3bFilter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [activeHeaderFilter, setActiveHeaderFilter] = useState<'r1' | 'r3b' | null>(null);

  // Modal States
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [visiblePasswords, setVisiblePasswords] = useState<Set<string>>(new Set());

  // Integrated Period-Specific Logic
  const { getStatus, toggleStatus } = useMonthlyFilingLogic(selectedYear, selectedMonth);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      // Only Monthly regular taxpayers
      const monthlyFilers = data.filter(c => c.gstProfile?.filingFreq === 'Monthly');
      setClients(monthlyFilers);
    } catch (error) {
      console.error("Failed to fetch monthly filers", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const togglePasswordVisibility = (clientId: string) => {
    setVisiblePasswords(prev => {
      const next = new Set(prev);
      if (next.has(clientId)) next.delete(clientId);
      else next.add(clientId);
      return next;
    });
  };

  const filteredClients = useMemo(() => {
    let list = clients.filter(c => 
      (c.legalName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.tradeName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.gstProfile?.gstin || '').toLowerCase().includes(search.toLowerCase())
    );

    // Apply GSTR-1 Filter
    if (r1Filter !== 'All') {
      list = list.filter(c => {
        const filed = getStatus(c.id).r1;
        return r1Filter === 'Filed' ? filed : !filed;
      });
    }

    // Apply GSTR-3B Filter
    if (r3bFilter !== 'All') {
      list = list.filter(c => {
        const filed = getStatus(c.id).r3b;
        return r3bFilter === 'Filed' ? filed : !filed;
      });
    }

    return list;
  }, [clients, search, r1Filter, r3bFilter, selectedYear, selectedMonth]);

  const stats = useMemo(() => {
    const total = filteredClients.length;
    const r1Filed = filteredClients.filter(c => getStatus(c.id).r1).length;
    const r3bFiled = filteredClients.filter(c => getStatus(c.id).r3b).length;
    return { total, r1Filed, r3bFiled };
  }, [filteredClients, selectedYear, selectedMonth]);

  const handleExport = () => {
    const headers = ["S.No", "Trade Name", "Legal Name", "GSTIN", "Portal ID", "Password", "GSTR-1", "GSTR-3B", "Period"].join(",");
    const rows = filteredClients.map((c, idx) => {
      const st = getStatus(c.id);
      return [
        idx + 1,
        c.tradeName || "---",
        c.legalName,
        c.gstProfile?.gstin,
        c.gstProfile?.username,
        c.gstProfile?.password,
        st.r1 ? "FILED" : "PENDING",
        st.r3b ? "FILED" : "PENDING",
        `${selectedMonth} ${selectedYear}`
      ].join(",");
    }).join("\n");
    const blob = new Blob([headers + "\n" + rows], { type: 'text/csv' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `Compliance_${selectedMonth}_${selectedYear}.csv`;
    link.click();
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500">

      {/* Dynamic Header Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Period: {selectedMonth}</p>
            <p className="text-xl font-black text-slate-900 leading-none">{stats.total}</p>
          </div>
          <div className="text-center">
            <p className="text-[9px] font-black text-emerald-500 uppercase tracking-widest mb-1">R1 Filed</p>
            <p className="text-xl font-black text-emerald-600 leading-none">{stats.r1Filed}</p>
          </div>
          <div className="text-center">
            <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mb-1">3B Filed</p>
            <p className="text-xl font-black text-indigo-600 leading-none">{stats.r3bFiled}</p>
          </div>
        </div>

        <div className="relative flex-1 w-full group">
          <input type="text" placeholder="Quick search..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 transition-all outline-none" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="bg-slate-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest text-slate-600 outline-none cursor-pointer">
            {YEARS.map(y => <option key={y} value={y}>{y}</option>)}
          </select>
          <select value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)} className="bg-slate-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest text-slate-600 outline-none cursor-pointer">
            {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
        </div>

        <button onClick={handleExport} className="h-12 px-6 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-emerald-600 transition-all flex items-center gap-2 shrink-0">
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
          Export
        </button>
      </div>

      {/* Main Table Content */}
      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-auto min-w-[1400px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-5 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 w-16">S.No</th>
                <th className="px-5 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Trade Name</th>
                <th className="px-5 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Legal Name</th>
                <th className="px-5 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">GSTIN</th>

                <th className="px-5 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-center relative">
                  <div className="flex items-center justify-center gap-2">
                    GSTR-1
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'r1' ? null : 'r1')} className={`p-1 rounded transition-colors ${r1Filter !== 'All' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:bg-slate-200'}`}>
                      <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {activeHeaderFilter === 'r1' && (
                    <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      {['All', 'Filed', 'Pending'].map(f => (
                        <button key={f} onClick={() => { setR1Filter(f as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[10px] font-black uppercase rounded-lg ${r1Filter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>{f}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-5 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-center relative">
                   <div className="flex items-center justify-center gap-2">
                    GSTR-3B
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'r3b' ? null : 'r3b')} className={`p-1 rounded transition-colors ${r3bFilter !== 'All' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:bg-slate-200'}`}>
                      <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {activeHeaderFilter === 'r3b' && (
                    <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      {['All', 'Filed', 'Pending'].map(f => (
                        <button key={f} onClick={() => { setR3bFilter(f as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[10px] font-black uppercase rounded-lg ${r3bFilter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>{f}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-5 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">User ID</th>
                <th className="px-5 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Password</th>
                <th className="px-5 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right w-32">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredClients.map((client, idx) => {
                const st = getStatus(client.id);
                const isVisible = visiblePasswords.has(client.id);

                return (
                  <tr key={client.id} className="group hover:bg-slate-50/50 transition-colors">
                    <td className="px-5 py-5 text-xs font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                    <td className="px-5 py-5 text-sm font-black text-slate-900 uppercase truncate max-w-[150px]">{client.tradeName || '---'}</td>
                    <td className="px-5 py-5 text-xs font-bold text-slate-500 uppercase truncate max-w-[150px]">{client.legalName}</td>
                    <td className="px-5 py-5">
                      <span className="text-[11px] font-black text-indigo-600 font-mono tracking-widest">{client.gstProfile?.gstin}</span>
                    </td>

                    <td className="px-5 py-5 text-center">
                      <button onClick={() => toggleStatus(client.id, 'r1')} className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${st.r1 ? 'bg-emerald-100 text-emerald-700 shadow-sm' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>
                        <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4" /></svg>{st.r1 ? 'Filed' : 'Pending'}</button>
                    </td>

                    <td className="px-5 py-5 text-center">
                      <button onClick={() => toggleStatus(client.id, 'r3b')} className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${st.r3b ? 'bg-indigo-100 text-indigo-700 shadow-sm' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>
                        <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4" /></svg>{st.r3b ? 'Filed' : 'Pending'}</button>
                    </td>

                    <td className="px-5 py-5">
                       <span className="text-xs font-black text-slate-700">{client.gstProfile?.username}</span>
                    </td>

                    <td className="px-5 py-5">
                       <div className="flex items-center gap-2">
                          <span className="text-xs font-black text-indigo-600 tracking-wider">{isVisible ? client.gstProfile?.password : '••••••••'}</span>
                          <button onClick={() => togglePasswordVisibility(client.id)} className="text-slate-300 hover:text-indigo-600">
                             {isVisible ? <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg> : <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>}
                          </button>
                       </div>
                    </td>

                    <td className="px-5 py-5 text-right">
                       <div className="flex items-center justify-end gap-2">
                          <button onClick={() => {
                            navigator.clipboard.writeText(client.gstProfile?.username || '');
                            window.open('https://services.gst.gov.in/services/login', '_blank');
                          }} className="h-9 w-9 rounded-xl bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center shadow-sm" title="Login Portal">
                             <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
                          </button>
                          <button onClick={() => { setSelectedClient(client); setIsDetailModalOpen(true); }} className="h-9 w-9 rounded-xl bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center shadow-sm" title="View Detail">
                             <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                          </button>
                       </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        <div className="px-8 py-4 bg-slate-50 border-t border-slate-100 flex items-center justify-between shrink-0">
           <p className="text-[9px] font-black uppercase tracking-widest text-slate-400">Compliance Period: {selectedMonth} {selectedYear}</p>
           <div className="flex items-center gap-4"><span className="text-[9px] font-black uppercase text-indigo-600 animate-pulse tracking-widest">Master Vault Sync Active</span></div>
        </div>
      </div>

      <GSTClientFormModal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} onSave={() => fetchClients()} initialData={selectedClient} />

      {/* DETAIL MODAL */}
      {isDetailModalOpen && selectedClient && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
          <div className="w-full max-w-5xl max-h-[95vh] bg-white rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <div className="px-10 py-8 bg-slate-50 border-b border-slate-100 flex items-center justify-between shrink-0">
              <div>
                 <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">{selectedClient.tradeName || selectedClient.legalName}</h2>
                 <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">Compliance Vault Record</p>
              </div>
              <div className="flex items-center gap-3">
                <button onClick={() => { if(confirm('Delete?')) mockBackend.deleteClient(selectedClient.id).then(() => { setIsDetailModalOpen(false); fetchClients(); }); }} className="h-10 px-6 bg-white border border-red-100 text-red-600 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-red-50">Delete</button>
                <button onClick={() => { setIsEditModalOpen(true); setIsDetailModalOpen(false); }} className="h-10 px-8 bg-indigo-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-slate-900 transition-all">Edit</button>
                <button onClick={() => setIsDetailModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-200 transition-colors">
                  <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
                </button>
              </div>
            </div>

            <div className="p-10 overflow-y-auto no-scrollbar flex-1 space-y-12">
               <section>
                  <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6 flex items-center gap-3">Business Profile <div className="h-px flex-1 bg-slate-100" /></h4>
                  <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                     <div className="md:col-span-2">
                        <p className="text-[9px] font-black uppercase text-slate-400 mb-1">GSTIN Identifier</p>
                        <p className="text-xl font-black text-indigo-600 font-mono tracking-widest">{selectedClient.gstProfile?.gstin}</p>
                     </div>
                     <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Entity Status</p><p className="text-sm font-black text-slate-900 uppercase">{selectedClient.status}</p></div>
                     <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Mobile No</p><p className="text-sm font-black text-slate-900">{selectedClient.mobile || 'N/A'}</p></div>
                  </div>
               </section>

               <section>
                  <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6 flex items-center gap-3">Vault Credentials <div className="h-px flex-1 bg-slate-100" /></h4>
                  <div className="flex flex-col md:flex-row gap-4 items-stretch">
                     <div className="flex-1 bg-slate-50 p-4 rounded-2xl border border-slate-100 flex items-center justify-between">
                        <div><p className="text-[9px] font-black uppercase text-slate-400">User ID</p><p className="text-base font-black text-slate-900">{selectedClient.gstProfile?.username}</p></div>
                        <button onClick={() => { navigator.clipboard.writeText(selectedClient.gstProfile?.username || ''); alert('Copied'); }} className="h-10 w-10 flex items-center justify-center rounded-xl bg-white text-slate-400 hover:text-indigo-600 shadow-sm transition-all"><svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2" /></svg></button>
                     </div>
                     <div className="flex-[1.5] bg-slate-50 p-4 rounded-2xl border border-slate-100 flex items-center gap-4">
                        <div className="flex-1">
                           <p className="text-[9px] font-black uppercase text-slate-400">Vault Password</p>
                           <p className="text-base font-black text-slate-900 tracking-wider">{selectedClient.gstProfile?.password}</p>
                        </div>
                        <button onClick={() => window.open('https://services.gst.gov.in/services/login', '_blank')} className="px-8 h-12 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-slate-900 transition-all flex items-center gap-2">
                           <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 16l-4-4m0 0l4-4" /></svg> Login Portal
                        </button>
                     </div>
                  </div>
               </section>
            </div>

            <div className="p-8 border-t border-slate-100 bg-slate-50/50 flex flex-col gap-6 shrink-0">
               <div className="flex items-center justify-between gap-4"><div className="flex-1 h-px bg-slate-200" /><span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] whitespace-nowrap px-2">Vault Secure Share</span><div className="flex-1 h-px bg-slate-200" /></div>
               <div className="flex flex-wrap items-center justify-center gap-4">
                  <button onClick={() => window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(`*GST Credentials for ${selectedClient.tradeName}*\n\nGSTIN: ${selectedClient.gstProfile?.gstin}\nUser: ${selectedClient.gstProfile?.username}\nPass: ${selectedClient.gstProfile?.password}`)}`, '_blank')} className="flex items-center gap-3 h-14 px-8 bg-white border border-slate-200 rounded-2xl text-[11px] font-black uppercase tracking-widest text-slate-600 hover:border-emerald-500 hover:text-emerald-600 transition-all shadow-sm">
