import { useState, useEffect } from 'react';

export interface FilingStatus {
  r1: boolean;
  r3b: boolean;
}

const STORAGE_KEY = 'clientify_filing_master_data';

export const YEARS = ['2023-24', '2024-25', '2025-26'];
export const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June', 
  'July', 'August', 'September', 'October', 'November', 'December'
];

export const getDefaultPeriod = () => {
  const now = new Date();
  let monthIdx = now.getMonth() - 1; // Previous month
  let year = '2024-25'; // Default fallback

  if (monthIdx < 0) {
    monthIdx = 11; // December of previous year
    year = '2023-24';
  }

  return {
    month: MONTHS[monthIdx],
    year: year
  };
};

export const useMonthlyFilingLogic = (selectedYear: string, selectedMonth: string) => {
  const periodKey = `${selectedYear}_${selectedMonth}`;
  const [allFilingData, setAllFilingData] = useState<Record<string, Record<string, FilingStatus>>>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : {};
  });

  const toggleStatus = (clientId: string, type: 'r1' | 'r3b') => {
    const periodData = allFilingData[periodKey] || {};
    const clientData = periodData[clientId] || { r1: false, r3b: false };

    const nextData = {
      ...allFilingData,
      [periodKey]: {
        ...periodData,
        [clientId]: {
          ...clientData,
          [type]: !clientData[type]
        }
      }
    };

    setAllFilingData(nextData);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(nextData));
  };

  const getStatus = (clientId: string): FilingStatus => {
    return (allFilingData[periodKey] || {})[clientId] || { r1: false, r3b: false };
  };

  return {
    getStatus,
    toggleStatus,
    currentPeriodData: allFilingData[periodKey] || {}
  };
};

