import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import GSTClientFormModal from '../../Clientform/GSTClientFormModal';
import Loader from '../../../components/Loader';
import { useMonthlyFilingLogic, MONTHS, YEARS, getDefaultPeriod } from './filinglogic/MonthlyFilingLogic';

const QuarterlyFiling: React.FC = () => {
  const defaultPeriod = getDefaultPeriod();
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState(defaultPeriod.year);
  const [selectedMonth, setSelectedMonth] = useState(defaultPeriod.month);

  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [visiblePasswords, setVisiblePasswords] = useState<Set<string>>(new Set());

  const { getStatus, toggleStatus } = useMonthlyFilingLogic(selectedYear, selectedMonth);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      // Filter: Active Filing + (Regular + Quarterly) + (Active or Suspended GSTIN)
      const filtered = data.filter(c => 
        c.status === 'Active Filing' && 
        c.gstProfile?.regType === 'Regular' &&
        c.gstProfile?.filingFreq === 'Quarterly' &&
        (c.gstProfile?.gstStatus === 'Active' || c.gstProfile?.gstStatus === 'Suspended')
      );
      setClients(filtered);
    } finally { setIsLoading(false); }
  };

  useEffect(() => { fetchClients(); }, []);

  const filteredClients = useMemo(() => clients.filter(c => 
    (c.legalName || '').toLowerCase().includes(search.toLowerCase()) || 
    (c.tradeName || '').toLowerCase().includes(search.toLowerCase()) || 
    (c.gstProfile?.gstin || '').toLowerCase().includes(search.toLowerCase())
  ), [clients, search]);

  const stats = useMemo(() => ({
    total: filteredClients.length,
    r1Filed: filteredClients.filter(c => getStatus(c.id).r1).length,
    r3bFiled: filteredClients.filter(c => getStatus(c.id).r3b).length,
  }), [filteredClients, getStatus]);

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 max-w-[1550px] mx-auto w-full">
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center"><p className="text-[9px] font-black text-slate-400 uppercase mb-1">Quarterly filers</p><p className="text-xl font-black text-slate-900">{stats.total}</p></div>
          <div className="text-center"><p className="text-[9px] font-black text-emerald-500 uppercase mb-1">R1/IFF Filed</p><p className="text-xl font-black text-emerald-600">{stats.r1Filed}</p></div>
          <div className="text-center"><p className="text-[9px] font-black text-indigo-500 uppercase mb-1">3B Filed</p><p className="text-xl font-black text-indigo-600">{stats.r3bFiled}</p></div>
        </div>
        <div className="relative flex-1 w-full"><input type="text" placeholder="Search entity..." value={search} onChange={e => setSearch(e.target.value)} className="w-full bg-slate-50 border-none rounded-xl py-3 pl-10 pr-4 font-bold text-sm" /></div>
        <div className="flex items-center gap-2">
          <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="bg-slate-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase"><{YEARS.map(y => <option key={y}>{y}</option>)}</select>
          <select value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)} className="bg-slate-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase"><{MONTHS.map(m => <option key={m}>{m}</option>)}</select>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1250px]">
            <thead className="sticky top-0 z-20"><tr className="bg-slate-50 border-b border-slate-100"><th className="px-4 py-5 w-[50px] text-[10px] font-black uppercase text-slate-400">S.No</th><th className="px-4 py-5 w-[170px] text-[10px] font-black uppercase text-slate-400">Trade Name</th><th className="px-4 py-5 w-[170px] text-[10px] font-black uppercase text-slate-400">Legal Name</th><th className="px-4 py-5 w-[160px] text-[10px] font-black uppercase text-slate-400">GSTIN</th><th className="px-4 py-5 w-[100px] text-center text-[10px] font-black uppercase text-slate-400">GSTR-1</th><th className="px-4 py-5 w-[100px] text-center text-[10px] font-black uppercase text-slate-400">GSTR-3B</th><th className="px-4 py-5 w-[140px] text-[10px] font-black uppercase text-slate-400">User ID</th><th className="px-4 py-5 w-[180px] text-[10px] font-black uppercase text-slate-400">Password</th><th className="px-4 py-5 w-[110px] text-right text-[10px] font-black uppercase text-slate-400">Actions</th></tr></thead>
            <tbody className="divide-y divide-slate-100">{filteredClients.map((client, idx) => {
              const st = getStatus(client.id);
              const isVisible = visiblePasswords.has(client.id);
              return (<tr key={client.id} className="group hover:bg-slate-50/50"><td className="px-4 py-5 text-xs font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td><td className="px-4 py-5 text-sm font-black truncate">{client.tradeName || '---'}</td><td className="px-4 py-5 text-xs font-bold truncate">{client.legalName}</td><td className="px-4 py-5"><span className="text-[11px] font-black text-indigo-600 font-mono">{client.gstProfile?.gstin}</span></td><td className="px-4 py-5 text-center"><button onClick={() => toggleStatus(client.id, 'r1')} className={`px-3 py-1.5 rounded-full text-[9px] font-black uppercase ${st.r1 ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-400'}`}>{st.r1 ? 'Filed' : 'Pending'}</button></td><td className="px-4 py-5 text-center"><button onClick={() => toggleStatus(client.id, 'r3b')} className={`px-3 py-1.5 rounded-full text-[9px] font-black uppercase ${st.r3b ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 text-slate-400'}`}>{st.r3b ? 'Filed' : 'Pending'}</button></td><td className="px-4 py-5 truncate text-xs font-black">{client.gstProfile?.username}</td><td className="px-4 py-5"><div className="flex items-center gap-2"><span className="text-[11px] font-black text-indigo-600 tracking-wider truncate max-w-[80px]">{isVisible ? client.gstProfile?.password : '••••••••'}</span><button onClick={() => setVisiblePasswords(prev => { const n = new Set(prev); n.has(client.id) ? n.delete(client.id) : n.add(client.id); return n; })} className="text-slate-300 hover:text-indigo-600 p-1"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg></button></div></td><td className="px-4 py-5 text-right flex justify-end gap-2"><button onClick={() => { setSelectedClient(client); setIsDetailModalOpen(true); }} className="h-9 w-9 rounded-xl bg-slate-50 border border-slate-200 flex items-center justify-center hover:text-indigo-600 transition-all"><svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg></button></td></tr>);})}</tbody>
          </table>
        </div>
