import { useState, useEffect, useCallback } from 'react';

export interface FilingStatus {
  r1: boolean;
  r3b: boolean;
}

const STORAGE_KEY = 'clientify_monthly_filing_v3';

export const YEARS = ['2023-24', '2024-25', '2025-26'];
export const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June', 
  'July', 'August', 'September', 'October', 'November', 'December'
];

export const getDefaultPeriod = () => {
  const now = new Date();
  let monthIdx = now.getMonth() - 1; 
  let year = '2024-25'; 

  if (monthIdx < 0) {
    monthIdx = 11;
    year = '2023-24';
  }

  return { month: MONTHS[monthIdx], year };
};

export const useMonthlyFilingLogic = (selectedYear: string, selectedMonth: string) => {
  const periodKey = `${selectedYear}_${selectedMonth}`;

  const [allData, setAllData] = useState<Record<string, Record<string, FilingStatus>>>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : {};
  });

  const toggleStatus = useCallback((clientId: string, type: 'r1' | 'r3b') => {
    setAllData(prev => {
      const periodData = { ...(prev[periodKey] || {}) };
      const clientData = { ...(periodData[clientId] || { r1: false, r3b: false }) };
      clientData[type] = !clientData[type];
      periodData[clientId] = clientData;
      const next = { ...prev, [periodKey]: periodData };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      return next;
    });
  }, [periodKey]);

  const getStatus = useCallback((clientId: string): FilingStatus => {
    return (allData[periodKey] || {})[clientId] || { r1: false, r3b: false };
  }, [allData, periodKey]);

  return { getStatus, toggleStatus };
};

