               <section className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div><h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6 flex items-center gap-3">Bank Details <div className="h-px flex-1 bg-slate-100" /></h4><div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-3"><div className="flex justify-between"><span className="text-[9px] font-black uppercase text-slate-400">Bank</span><span className="text-sm font-black text-slate-900">{selectedClient.bankDetails?.bankName || 'N/A'}</span></div><div className="flex justify-between"><span className="text-[9px] font-black uppercase text-slate-400">Account</span><span className="text-sm font-black text-slate-900 font-mono">{selectedClient.bankDetails?.accountNo || 'N/A'}</span></div><div className="flex justify-between"><span className="text-[9px] font-black uppercase text-slate-400">IFSC</span><span className="text-sm font-black text-indigo-600 font-mono">{selectedClient.bankDetails?.ifsc || 'N/A'}</span></div></div></div>
                  <div><h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6 flex items-center gap-3">Remarks <div className="h-px flex-1 bg-slate-100" /></h4><div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 min-h-[120px]"><p className="text-sm font-medium text-slate-600 italic leading-relaxed">{selectedClient.remarks || 'No specific notes.'}</p></div></div>
               </section>
