import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import GSTClientFormModal from '../../Clientform/GSTClientFormModal';
import Loader from '../../../components/Loader';
import { useQuarterlyFilingLogic, MONTHS, YEARS } from './filinglogic/QuarterlyFilingLogic';
import { getDefaultPeriod } from './filinglogic/MonthlyFilingLogic';

const QuarterlyFiling: React.FC = () => {
  const defaultPeriod = getDefaultPeriod();
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState(defaultPeriod.year);
  const [selectedMonth, setSelectedMonth] = useState(defaultPeriod.month);

  const [r1Filter, setR1Filter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [r3bFilter, setR3bFilter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [activeHeaderFilter, setActiveHeaderFilter] = useState<'r1' | 'r3b' | null>(null);

  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [visiblePasswords, setVisiblePasswords] = useState<Set<string>>(new Set());

  const { getStatus, toggleStatus } = useQuarterlyFilingLogic(selectedYear, selectedMonth);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      // Filter: Active Filing + Regular + Quarterly filers
      const filtered = data.filter(c => 
        c.status === 'Active Filing' && 
        c.gstProfile?.regType === 'Regular' &&
        c.gstProfile?.filingFreq === 'Quarterly' &&
        (c.gstProfile?.gstStatus === 'Active' || c.gstProfile?.gstStatus === 'Suspended')
      );
      setClients(filtered);
    } finally { setIsLoading(false); }
  };

  useEffect(() => { fetchClients(); }, []);

  const filteredClients = useMemo(() => {
    let list = clients.filter(c => 
      (c.legalName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.tradeName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.gstProfile?.gstin || '').toLowerCase().includes(search.toLowerCase())
    );
    if (r1Filter !== 'All') list = list.filter(c => r1Filter === 'Filed' ? getStatus(c.id).r1 : !getStatus(c.id).r1);
    if (r3bFilter !== 'All') list = list.filter(c => r3bFilter === 'Filed' ? getStatus(c.id).r3b : !getStatus(c.id).r3b);
    return list;
  }, [clients, search, r1Filter, r3bFilter, getStatus]);

  const stats = useMemo(() => ({
    total: filteredClients.length,
    r1Filed: filteredClients.filter(c => c.gstProfile?.gstStatus === 'Active' && getStatus(c.id).r1).length,
    r3bFiled: filteredClients.filter(c => c.gstProfile?.gstStatus === 'Active' && getStatus(c.id).r3b).length,
  }), [filteredClients, getStatus]);

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 max-w-[1580px] mx-auto w-full">
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center"><p className="text-[9px] font-black text-slate-400 uppercase mb-1">Quarterly filers</p><p className="text-xl font-black text-slate-900">{stats.total}</p></div>
          <div className="text-center"><p className="text-[9px] font-black text-emerald-500 uppercase mb-1">R1/IFF Filed</p><p className="text-xl font-black text-emerald-600">{stats.r1Filed}</p></div>
          <div className="text-center"><p className="text-[9px] font-black text-indigo-500 uppercase mb-1">3B Filed</p><p className="text-xl font-black text-indigo-600">{stats.r3bFiled}</p></div>
        </div>
        <div className="relative flex-1 w-full group">
          <input type="text" placeholder="Search QRMP entity..." value={search} onChange={e => setSearch(e.target.value)} className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 outline-none" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>
        <div className="flex items-center gap-2 shrink-0">
          <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="bg-slate-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest text-slate-600">{YEARS.map(y => <option key={y}>{y}</option>)}</select>
          <select value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)} className="bg-slate-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest text-slate-600">{MONTHS.map(m => <option key={m}>{m}</option>)}</select>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1250px]">
            <thead className="sticky top-0 z-20"><tr className="bg-slate-50 border-b border-slate-100"><th className="px-4 py-5 text-[10px] font-black uppercase text-slate-400 w-[50px]">S.No</th><th className="px-4 py-5 text-[10px] font-black uppercase text-slate-400 w-[170px]">Trade Name</th><th className="px-4 py-5 text-[10px] font-black uppercase text-slate-400 w-[170px]">Legal Name</th><th className="px-4 py-5 text-[10px] font-black uppercase text-slate-400 w-[200px]">GSTIN</th><th className="px-4 py-5 text-[10px] font-black uppercase text-slate-400 text-center w-[100px]">IFF/GSTR-1</th><th className="px-4 py-5 text-[10px] font-black uppercase text-slate-400 text-center w-[100px]">GSTR-3B</th><th className="px-4 py-5 text-[10px] font-black uppercase text-slate-400 w-[140px]">User ID</th><th className="px-4 py-5 text-[10px] font-black uppercase text-slate-400 w-[180px]">Password</th><th className="px-4 py-5 text-[10px] font-black uppercase text-slate-400 text-right w-[100px]">Actions</th></tr></thead>
            <tbody className="divide-y divide-slate-100">{filteredClients.map((client, idx) => {
              const st = getStatus(client.id);
