import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import GSTClientFormModal from '../../Clientform/GSTClientFormModal';
import Loader from '../../../components/Loader';
import { useMonthlyFilingLogic, MONTHS, YEARS, getDefaultPeriod } from './filinglogic/MonthlyFilingLogic';

const MonthlyFiling: React.FC = () => {
  const defaultPeriod = getDefaultPeriod();
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState(defaultPeriod.year);
  const [selectedMonth, setSelectedMonth] = useState(defaultPeriod.month);

  const [r1Filter, setR1Filter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [r3bFilter, setR3bFilter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [activeHeaderFilter, setActiveHeaderFilter] = useState<'r1' | 'r3b' | null>(null);

  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);

  const [visiblePasswords, setVisiblePasswords] = useState<Set<string>>(new Set());
  const [editingPasswordId, setEditingPasswordId] = useState<string | null>(null);
  const [newPasswordValue, setNewPasswordValue] = useState('');

  const { getStatus, toggleStatus, allData } = useMonthlyFilingLogic(selectedYear, selectedMonth);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      const filtered = data.filter(c => 
        c.status === 'Active Filing' && 
        c.gstProfile?.regType === 'Regular' &&
        c.gstProfile?.filingFreq === 'Monthly' &&
        (c.gstProfile?.gstStatus === 'Active' || c.gstProfile?.gstStatus === 'Suspended')
      );
      setClients(filtered);
    } finally { setIsLoading(false); }
  };

  useEffect(() => { fetchClients(); }, []);

  const savePassword = async (client: Client) => {
    try {
      const updated = { ...client, gstProfile: { ...client.gstProfile!, password: newPasswordValue } };
      await mockBackend.saveClient(updated);
      setClients(prev => prev.map(c => c.id === client.id ? (updated as Client) : c));
      setEditingPasswordId(null);
    } catch (err) { alert("Failed to update password"); }
  };

  const filteredClients = useMemo(() => {
    let list = clients.filter(c => 
      (c.legalName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.tradeName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.gstProfile?.gstin || '').toLowerCase().includes(search.toLowerCase())
    );

    if (r1Filter !== 'All') list = list.filter(c => r1Filter === 'Filed' ? getStatus(c.id).r1 : !getStatus(c.id).r1);
    if (r3bFilter !== 'All') list = list.filter(c => r3bFilter === 'Filed' ? getStatus(c.id).r3b : !getStatus(c.id).r3b);

    return list;
  }, [clients, search, r1Filter, r3bFilter, getStatus, allData]); // allData added to force re-render

  const stats = useMemo(() => {
    const total = filteredClients.length;
    const r1Filed = filteredClients.filter(c => c.gstProfile?.gstStatus === 'Active' && getStatus(c.id).r1).length;
    const r3bFiled = filteredClients.filter(c => c.gstProfile?.gstStatus === 'Active' && getStatus(c.id).r3b).length;
    return { total, r1Filed, r3bFiled };
  }, [filteredClients, getStatus, allData]);

  const handleExport = () => {
    const headers = ["S.No", "Trade Name", "Legal Name", "GSTIN", "User ID", "Password", "GSTR-1", "GSTR-3B"].join(",");
    const rows = filteredClients.map((c, i) => [
      i + 1, c.tradeName, c.legalName, c.gstProfile?.gstin, c.gstProfile?.username, c.gstProfile?.password,
      getStatus(c.id).r1 ? "FILED" : "PENDING", getStatus(c.id).r3b ? "FILED" : "PENDING"
    ].join(",")).join("\n");
    const blob = new Blob([headers + "\n" + rows], { type: 'text/csv' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `Monthly_Filing_${selectedMonth}.csv`;
    link.click();
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-3 max-w-[1600px] mx-auto w-full px-2 animate-in fade-in duration-500">

      {/* Header Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-3 bg-white p-2.5 rounded-[1.25rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-5 px-3 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center min-w-[50px]"><p className="text-[9px] font-black text-slate-400 uppercase mb-1">{selectedMonth}</p><p className="text-lg font-black text-slate-900 leading-none">{stats.total}</p></div>
          <div className="text-center min-w-[50px]"><p className="text-[9px] font-black text-emerald-500 uppercase mb-1">R1 Filed</p><p className="text-lg font-black text-emerald-600 leading-none">{stats.r1Filed}</p></div>
          <div className="text-center min-w-[50px]"><p className="text-[9px] font-black text-indigo-500 uppercase mb-1">3B Filed</p><p className="text-lg font-black text-indigo-600 leading-none">{stats.r3bFiled}</p></div>
        </div>

        <div className="relative flex-1 w-full group">
          <input type="text" placeholder="Search..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-2.5 pl-10 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" />
          <svg className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="bg-slate-50 border-none rounded-xl px-3 py-2.5 text-[11px] font-black uppercase text-slate-600 outline-none">{YEARS.map(y => <option key={y}>{y}</option>)}</select>
          <select value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)} className="bg-slate-50 border-none rounded-xl px-3 py-2.5 text-[11px] font-black uppercase text-slate-600 outline-none">{MONTHS.map(m => <option key={m}>{m}</option>)}</select>
          <button onClick={handleExport} className="h-10 w-10 flex items-center justify-center bg-slate-900 text-white rounded-xl shadow-lg hover:bg-emerald-600 transition-all"><svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg></button>
        </div>
      </div>

      {/* Main Table */}
      <div className="flex-1 bg-white rounded-[1.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1100px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-3 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 w-[50px]">S.No</th>
                <th className="px-3 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Trade Name</th>
                <th className="px-3 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Legal Name</th>
                <th className="px-3 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 w-[160px]">GSTIN</th>
                <th className="px-3 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 text-center w-[90px] relative">
                   <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'r1' ? null : 'r1')} className="flex items-center justify-center gap-1 w-full">GSTR-1 <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg></button>
                   {activeHeaderFilter === 'r1' && <div className="absolute top-full left-0 w-28 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">{['All', 'Filed', 'Pending'].map(f => <button key={f} onClick={() => { setR1Filter(f as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-2 py-2 text-[10px] font-black uppercase rounded-lg ${r1Filter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{f}</button>)}</div>}
                </th>
                <th className="px-3 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 text-center w-[90px] relative">
                   <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'r3b' ? null : 'r3b')} className="flex items-center justify-center gap-1 w-full">GSTR-3B <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg></button>
                   {activeHeaderFilter === 'r3b' && <div className="absolute top-full left-0 w-28 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">{['All', 'Filed', 'Pending'].map(f => <button key={f} onClick={() => { setR3bFilter(f as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-2 py-2 text-[10px] font-black uppercase rounded-lg ${r3bFilter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{f}</button>)}</div>}
