                          <button onClick={() => { setSelectedClient(client); setIsDetailModalOpen(true); }} className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center"><svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg></button>
                       </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <GSTClientFormModal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} onSave={() => fetchClients()} initialData={selectedClient} />

      {/* FULL DETAIL MODAL - HIGH END VERSION */}
      {isDetailModalOpen && selectedClient && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
          <div className="w-full max-w-5xl max-h-[95vh] bg-white rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <div className="px-10 py-8 bg-slate-50 border-b border-slate-100 flex items-center justify-between shrink-0">
              <div className="min-w-0">
                 <h2 className="text-2xl font-black text-slate-900 uppercase truncate">{selectedClient.tradeName || selectedClient.legalName}</h2>
                 <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">{selectedClient.legalName}</p>
              </div>
              <div className="flex items-center gap-3 shrink-0">
                <button onClick={() => { if(confirm('Delete?')) mockBackend.deleteClient(selectedClient.id).then(() => { setIsDetailModalOpen(false); fetchClients(); }); }} className="h-10 px-6 bg-white border border-red-100 text-red-600 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-red-50">Delete</button>
                <button onClick={() => { setIsEditModalOpen(true); setIsDetailModalOpen(false); }} className="h-10 px-8 bg-indigo-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-slate-900 transition-all">Edit</button>
                <button onClick={() => setIsDetailModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-200 transition-colors"><svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg></button>
              </div>
            </div>
            <div className="p-10 overflow-y-auto no-scrollbar flex-1 space-y-10">
               <section>
                  <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6 flex items-center gap-3">Business Identity <div className="h-px flex-1 bg-slate-100" /></h4>
                  <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                     <div className="md:col-span-2"><p className="text-[9px] font-black uppercase text-slate-400 mb-1">GSTIN</p><p className="text-xl font-black text-indigo-600 font-mono tracking-widest">{selectedClient.gstProfile?.gstin}</p></div>
                     <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Status</p><p className="text-sm font-black text-slate-900 uppercase">{selectedClient.status}</p></div>
                     <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Mobile</p><p className="text-sm font-black text-slate-900">{selectedClient.mobile}</p></div>
                     <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">User ID</p><p className="text-sm font-black text-slate-900 uppercase">{selectedClient.gstProfile?.username}</p></div>
                     <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Password</p><p className="text-sm font-black text-slate-900 tracking-wider">{selectedClient.gstProfile?.password}</p></div>
                  </div>
               </section>
               <section className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div><h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6 flex items-center gap-3">Bank Details <div className="h-px flex-1 bg-slate-100" /></h4><div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-3"><div className="flex justify-between"><span className="text-[9px] font-black uppercase text-slate-400">Bank</span><span className="text-sm font-black text-slate-900">{selectedClient.bankDetails?.bankName || 'N/A'}</span></div><div className="flex justify-between"><span className="text-[9px] font-black uppercase text-slate-400">Account</span><span className="text-sm font-black text-slate-900 font-mono">{selectedClient.bankDetails?.accountNo || 'N/A'}</span></div><div className="flex justify-between"><span className="text-[9px] font-black uppercase text-slate-400">IFSC</span><span className="text-sm font-black text-indigo-600 font-mono">{selectedClient.bankDetails?.ifsc || 'N/A'}</span></div></div></div>
                  <div><h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6 flex items-center gap-3">Staff Remarks <div className="h-px flex-1 bg-slate-100" /></h4><div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 min-h-[120px]"><p className="text-sm font-medium text-slate-600 italic leading-relaxed">{selectedClient.remarks || 'No notes provided.'}</p></div></div>
