                <button onClick={handleExportCSV} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl border-t border-slate-50 mt-1">Export IT Data</button>
              </div>
            )}
          </div>

          <button onClick={() => setIsModalOpen(true)} className="bg-emerald-600 text-white font-black uppercase tracking-tight px-4 h-10 rounded-xl shadow-lg hover:bg-slate-900 transition-all flex items-center gap-2 text-sm">
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
            <span className="hidden sm:inline">Add IT Client</span>
            <span className="sm:hidden">+</span>
          </button>
        </div>
      </div>

      <div className="flex-1 min-h-0 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <ItMasterPortfolio 
          key={refreshTrigger} 
          externalSearch={search} 
          hideInternalSearch={true} 
          categoryFilter={categoryFilter}
          onDataChange={() => setRefreshTrigger(p => p + 1)}
        />
      </div>

      <ITClientFormModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={() => setRefreshTrigger(p => p + 1)} />
    </div>
  );
};

export default ITPortfolio;

import React, { useState, useEffect, useMemo } from 'react';
// Fixed: Changed from default import to named import to match updated export in GstMasterPortfolio.tsx
import { GstMasterPortfolio } from './GstMasterPortfolio';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import { mockBackend } from '../../services/mockBackend';
import { Client, JurisdictionType, ClientStatus, GstStatus, GstRegType, GstFilingFreq, ConstitutionType } from '../../types';

const CSV_HEADERS = [
  "Legal Name", "Trade Name", "Mobile", "Email", "Client Status",
  "GSTIN", "Portal Username", "Portal Password", "GST Status", 
  "Reg Date", "Cancel Date", "Reg Type", "Filing Freq", 
  "Constitution", "Jurisdiction", "Sector", "Range", 
  "Address", "Bank Name", "Account No", "IFSC", "Remarks"
];

const GSTPortfolio: React.FC = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [search, setSearch] = useState('');
  const [jurisdictionFilter, setJurisdictionFilter] = useState<JurisdictionType | 'All'>('All');
  const [sectorFilter, setSectorFilter] = useState<string>('All');
  const [rangeFilter, setRangeFilter] = useState<string>('All');
  const [showDataOptions, setShowDataOptions] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);

  useEffect(() => {
    const load = async () => {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.gstProfile));
    };
    load();
  }, [refreshTrigger]);

  const stats = useMemo(() => {
    const total = clients.length;
    const active = clients.filter(c => c.status === 'Active Filing').length;
    const caseStudy = clients.filter(c => c.status === 'Case-by-Case').length;
    const inactive = clients.filter(c => c.status.startsWith('Inactive')).length;
    return { total, active, caseStudy, inactive };
  }, [clients]);

  const sectors = useMemo(() => {
    const s = new Set<string>();
    clients.forEach(c => {
      if (c.gstProfile?.jurisdictionType === 'State' && c.gstProfile.sector) {
        s.add(c.gstProfile.sector);
      }
    });
    return Array.from(s).sort();
  }, [clients]);

  const ranges = useMemo(() => {
    const r = new Set<string>();
    clients.forEach(c => {
      if (c.gstProfile?.jurisdictionType === 'Center' && c.gstProfile.range) {
        r.add(c.gstProfile.range);
      }
    });
    return Array.from(r).sort();
  }, [clients]);

  const handleJurisdictionChange = (val: string) => {
    setJurisdictionFilter(val as any);
    setSectorFilter('All');
    setRangeFilter('All');
  };

  const handleExportCSV = () => {
    const rows = clients.map(c => [
      c.legalName,
      c.tradeName,
      c.mobile,
      c.email || "",
      c.status,
      c.gstProfile?.gstin,
      c.gstProfile?.username,
      c.gstProfile?.password || "",
      c.gstProfile?.gstStatus,
      c.gstProfile?.regDate,
      c.gstProfile?.cancelDate || "",
      c.gstProfile?.regType,
      c.gstProfile?.filingFreq,
      c.gstProfile?.constitution,
      c.gstProfile?.jurisdictionType,
      c.gstProfile?.sector || "",
      c.gstProfile?.range || "",
      `"${(c.gstProfile?.address || "").replace(/"/g, '""')}"`,
      c.bankDetails?.bankName || "",
      c.bankDetails?.accountNo || "",
      c.bankDetails?.ifsc || "",
      `"${(c.remarks || "").replace(/"/g, '""')}"`
    ]);
    const csvContent = [CSV_HEADERS, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `GST_Portfolio_Full_${new Date().toISOString().split('T')[0]}.csv`);
    link.click();
    setShowDataOptions(false);
  };

  const handleImportTemplateCSV = () => {
    const csvContent = [CSV_HEADERS].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "GST_Clientify_Template.csv");
    link.click();
    setShowDataOptions(false);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      const rows = text.split('\n').slice(1);
      const allClients = await mockBackend.getClients();

      let newCount = 0;
      let updatedCount = 0;
      let failedCount = 0;

      for (const row of rows) {
        if (!row.trim()) continue;
        const cols = row.split(',').map(c => c.trim().replace(/^"|"$/g, ''));
        if (cols.length < 6) continue;

        const gstin = cols[5];
        if (!gstin) continue;

        const existing = allClients.find(c => c.gstProfile?.gstin === gstin);

        try {
          await mockBackend.saveClient({
            id: existing?.id,
            legalName: cols[0],
            tradeName: cols[1],
            mobile: cols[2],
            email: cols[3],
            status: (cols[4] as ClientStatus) || 'Active Filing',
            gstProfile: {
              gstin,
              username: cols[6] || '',
              password: cols[7] || '',
              gstStatus: (cols[8] as GstStatus) || 'Active',
              regDate: cols[9] || new Date().toISOString().split('T')[0],
              cancelDate: cols[10] || undefined,
              regType: (cols[11] as GstRegType) || 'Regular',
              filingFreq: (cols[12] as GstFilingFreq) || 'Monthly',
              constitution: (cols[13] as ConstitutionType) || 'Proprietorship',
              jurisdictionType: (cols[14] as JurisdictionType) || 'State',
              sector: cols[15],
              range: cols[16],
              address: cols[17],
              stakeholders: existing?.gstProfile?.stakeholders || []
            },
            bankDetails: {
              bankName: cols[18] || '',
              accountNo: cols[19] || '',
              ifsc: cols[20] || ''
            },
            remarks: cols[21]
          });

          if (existing) {
            updatedCount++;
          } else {
            newCount++;
          }
        } catch (err) {
          failedCount++;
        }
      }

      const summary = `Import Result Summary:\n\n• New Clients Added: ${newCount}\n• Existing Records Updated: ${updatedCount}${failedCount > 0 ? `\n• Rows Failed: ${failedCount}` : ''}`;
      alert(summary);

      setRefreshTrigger(p => p + 1);
      setShowDataOptions(false);
    };
    reader.readAsText(file);
    event.target.value = ''; 
  };

  return (
    <div className="flex flex-col h-full space-y-3 pb-4 overflow-hidden">
      {/* Consolidated Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-3 bg-white p-2.5 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">

        {/* Status Indicators */}
        <div className="flex items-center gap-4 px-2 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="flex flex-col items-center min-w-[32px]">
            <span className="text-[9px] font-black text-slate-400 uppercase leading-none mb-1">Total</span>
            <span className="text-lg font-black text-slate-900 leading-none">{stats.total}</span>
          </div>
          <div className="flex flex-col items-center min-w-[32px]">
            <span className="text-[9px] font-black text-green-500 uppercase leading-none mb-1">Active</span>
            <span className="text-lg font-black text-green-600 leading-none">{stats.active}</span>
          </div>
          <div className="flex flex-col items-center min-w-[32px]">
            <span className="text-[9px] font-black text-amber-500 uppercase leading-none mb-1">Case</span>
            <span className="text-lg font-black text-amber-600 leading-none">{stats.caseStudy}</span>
          </div>
          <div className="flex flex-col items-center min-w-[32px]">
            <span className="text-[9px] font-black text-red-400 uppercase leading-none mb-1">Inact</span>
            <span className="text-lg font-black text-red-500 leading-none">{stats.inactive}</span>
          </div>
        </div>

        {/* Unified Search */}
        <div className="relative flex-1 group min-w-[180px] w-full">
          <input type="text" placeholder="Search legal name or GSTIN..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-2.5 pl-10 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 transition-all outline-none" />
          <svg className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        {/* Filters Group */}
        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar w-full lg:w-auto pb-1 lg:pb-0">
          <select value={jurisdictionFilter} onChange={e => handleJurisdictionChange(e.target.value)}
            className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-[11px] font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-indigo-600/10 outline-none shrink-0">
            <option value="All">Jurisdiction: All</option>
            <option value="State">State</option>
            <option value="Center">Center</option>
          </select>

          {jurisdictionFilter === 'State' && (
            <select value={sectorFilter} onChange={e => setSectorFilter(e.target.value)}
              className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-[11px] font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-indigo-600/10 outline-none animate-in fade-in slide-in-from-left-2 duration-300 shrink-0">
              <option value="All">All Sectors</option>
              {sectors.map(s => <option key={s} value={s}>{s}</option>)}
            </select>
          )}

          {jurisdictionFilter === 'Center' && (
            <select value={rangeFilter} onChange={e => setRangeFilter(e.target.value)}
              className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-[11px] font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-indigo-600/10 outline-none animate-in fade-in slide-in-from-left-2 duration-300 shrink-0">
              <option value="All">All Ranges</option>
              {ranges.map(r => <option key={r} value={r}>{r}</option>)}
            </select>
          )}
        </div>

        {/* Action Buttons */}
        <div className="flex items-center gap-2 shrink-0 ml-auto lg:ml-0">
          <div className="relative">
            <button onClick={() => setShowDataOptions(!showDataOptions)} className="h-10 w-10 flex items-center justify-center bg-slate-100 rounded-xl text-slate-600 hover:bg-indigo-600 hover:text-white transition-all shadow-sm">
               <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 7v10c0 2 1 3 3 3h10c2 0 3-1 3-3V7c0-2-1-3-3-3H7C5 4 4 5 4 7zm4 4h8m-8 4h5" /></svg>
            </button>
            {showDataOptions && (
              <div className="absolute right-0 mt-2 w-56 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 p-2 overflow-hidden animate-in zoom-in-95">
                <button onClick={handleImportTemplateCSV} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl">Download Template</button>
                <label className="w-full block px-4 py-3 text-[10px] font-black uppercase tracking-widest text-indigo-600 hover:bg-slate-50 rounded-xl cursor-pointer">
                  Bulk Import CSV <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
                </label>
                <button onClick={handleExportCSV} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl border-t border-slate-50 mt-1">Export All Data</button>
              </div>
            )}
          </div>

          <button onClick={() => setIsModalOpen(true)} className="bg-indigo-600 text-white font-black uppercase tracking-tight px-4 h-10 rounded-xl shadow-lg hover:bg-slate-900 transition-all flex items-center gap-2 text-sm whitespace-nowrap">
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
            <span className="hidden sm:inline">Add Client</span>
            <span className="sm:hidden">+</span>
          </button>
        </div>
      </div>

      <div className="flex-1 min-h-0 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <GstMasterPortfolio 
          key={refreshTrigger} 
          externalSearch={search} 
          hideInternalSearch={true} 
          jurisdictionFilter={jurisdictionFilter}
          sectorFilter={sectorFilter}
          rangeFilter={rangeFilter}
          onDataChange={() => setRefreshTrigger(p => p + 1)}
        />
      </div>

      <GSTClientFormModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={() => setRefreshTrigger(p => p + 1)} />
    </div>
  );
};

export default GSTPortfolio;

import React, { useState, useEffect, useMemo } from 'react';
import { Client, JurisdictionType } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import Loader from '../../components/Loader';

interface GstMasterPortfolioProps {
  externalSearch?: string;
  hideInternalSearch?: boolean;
  jurisdictionFilter?: JurisdictionType | 'All';
  sectorFilter?: string;
  rangeFilter?: string;
  onDataChange?: () => void;
}

// Fixed: Added 'export' to resolve 'no default export' error in parent component
export const GstMasterPortfolio: React.FC<GstMasterPortfolioProps> = ({ 
  externalSearch = '', 
  hideInternalSearch = false,
  jurisdictionFilter = 'All',
  sectorFilter = 'All',
  rangeFilter = 'All',
  onDataChange
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');

  const [isGstModalOpen, setIsGstModalOpen] = useState(false);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [activeMenuId, setActiveMenuId] = useState<string | null>(null);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const [tempPassword, setTempPassword] = useState('');
  const [showPassInView, setShowPassInView] = useState(false);
  const [isEditingPassword, setIsEditingPassword] = useState(false);
  const [localPassValue, setLocalPassValue] = useState('');
  const [showPassInLogin, setShowPassInLogin] = useState(false);
  const [isSavingPass, setIsSavingPass] = useState(false);

  const [gstStatusColFilter, setGstStatusColFilter] = useState<string>('All');
  const [clientStatusColFilter, setClientStatusColFilter] = useState<string>('All');

  const [openFilterCol, setOpenFilterCol] = useState<'gst' | 'status' | null>(null);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.gstProfile) || []);
    } catch (error) {
      console.error("Failed to fetch clients", error);
      setClients([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return 'N/A';
    if (!dateStr.includes('-')) return dateStr;
    const parts = dateStr.split('-');
    if (parts[0].length === 4) {
      return `${parts[2]}-${parts[1]}-${parts[0]}`;
    }
    return dateStr;
  };

  const filteredClients = useMemo(() => {
    let list = Array.isArray(clients) ? clients : [];

    if (jurisdictionFilter !== 'All') {
      list = list.filter(c => c.gstProfile?.jurisdictionType === jurisdictionFilter);
      if (jurisdictionFilter === 'State' && sectorFilter !== 'All') {
        list = list.filter(c => c.gstProfile?.sector === sectorFilter);
      }
      if (jurisdictionFilter === 'Center' && rangeFilter !== 'All') {
        list = list.filter(c => c.gstProfile?.range === rangeFilter);
      }
    }

    if (gstStatusColFilter !== 'All') {
      list = list.filter(c => c.gstProfile?.gstStatus === gstStatusColFilter);
    }
    if (clientStatusColFilter !== 'All') {
      list = list.filter(c => c.status === clientStatusColFilter);
    }

    const s = (externalSearch || search || '').toLowerCase();
    return list.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin && c.gstProfile.gstin.toLowerCase().includes(s)) || 
      (c.mobile || '').includes(s)
    );
  }, [clients, search, externalSearch, jurisdictionFilter, sectorFilter, rangeFilter, gstStatusColFilter, clientStatusColFilter]);

  const handleEdit = (client: Client) => {
    setSelectedClient(client);
    setIsGstModalOpen(true);
    setIsDetailModalOpen(false);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Are you sure you want to delete this client record?')) {
      await mockBackend.deleteClient(id);
      setIsDetailModalOpen(false);
      await fetchClients();
      if (onDataChange) onDataChange();
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const shareViaWhatsApp = (text: string) => {
    const url = `https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`;
    window.open(url, '_blank');
  };

  const handleFileShare = async (client: Client) => {
    const dataUrl = client.gstProfile?.certificateUrl;
    const title = `${client.tradeName || client.legalName} GST Certificate`;
    const text = getCertText(client);

    if (dataUrl && dataUrl.startsWith('data:application/pdf')) {
      try {
        const res = await fetch(dataUrl);
        const blob = await res.blob();
        const file = new File([blob], `${client.gstProfile?.gstin || 'GST'}_Certificate.pdf`, { type: 'application/pdf' });

        if (navigator.canShare && navigator.canShare({ files: [file] })) {
          await navigator.share({ files: [file], title, text });
          return;
        }
      } catch (err) {
        console.warn('File share failed', err);
      }
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = `${client.gstProfile?.gstin}_Certificate.pdf`;
      link.click();
      shareViaWhatsApp(text + "\n\n(Certificate downloaded separately)");
    } else {
      if (navigator.share) await navigator.share({ title, text });
      else shareViaWhatsApp(text);
    }
  };

  const handleUpdateGatewayPassword = async () => {
    if (!selectedClient) return;
    setIsSavingPass(true);
    try {
      const updatedClient = {
        ...selectedClient,
        gstProfile: { ...selectedClient.gstProfile!, password: tempPassword }
      };
      const saved = await mockBackend.saveClient(updatedClient);
      setSelectedClient(saved);
      await fetchClients();
      if (onDataChange) onDataChange();
      setTimeout(() => setIsSavingPass(false), 800);
    } catch (err) {
      console.error("Failed to update password", err);
      setIsSavingPass(false);
    }
  };

  const openPortalLogin = async (client: Client, finalPass?: string) => {
    if (finalPass && finalPass !== client.gstProfile?.password) {
      const updatedClient = {
        ...client,
        gstProfile: { ...client.gstProfile!, password: finalPass }
      };
      await mockBackend.saveClient(updatedClient);
      await fetchClients();
      if (onDataChange) onDataChange();
    }
    copyToClipboard(client.gstProfile?.username || '');
    window.open('https://services.gst.gov.in/services/login', '_blank');
  };

  const openPortalSearch = (gstin: string) => {
    copyToClipboard(gstin);
    window.open('https://services.gst.gov.in/services/searchtp', '_blank');
  };

  const saveQuickPasswordFromView = async () => {
    if (!selectedClient) return;
    const updatedClient = {
      ...selectedClient,
      gstProfile: { ...selectedClient.gstProfile!, password: localPassValue }
    };
    const saved = await mockBackend.saveClient(updatedClient);
    setSelectedClient(saved);
    setIsEditingPassword(false);
    await fetchClients();
    if (onDataChange) onDataChange();
  };

  const getCredText = (client: Client) => {
    return `*GST Credentials for ${client.tradeName || client.legalName}*\n\n*GSTIN:* ${client.gstProfile?.gstin}\n*Username:* ${client.gstProfile?.username}\n*Password:* ${client.gstProfile?.password}\n\n_Shared via Clientify_`;
  };

  const getCertText = (client: Client) => {
    return `*GST Registration Details: ${client.tradeName || client.legalName}*\n\n*GSTIN:* ${client.gstProfile?.gstin}\n*Status:* ${client.gstProfile?.gstStatus}\n*Reg Date:* ${formatDate(client.gstProfile?.regDate)}\n\n_Shared via Clientify_`;
  };

  const getFullShareText = (client: Client) => {
    const stakeholders = client.gstProfile?.stakeholders?.map(s => `• ${s.name} (${s.pan})`).join('\n') || 'None';
    return `*Clientify: Master Profile Share*\n\n*Trade Name:* ${client.tradeName}\n*Legal Name:* ${client.legalName}\n*GSTIN:* ${client.gstProfile?.gstin}\n*Mobile:* ${client.mobile}\n*Email:* ${client.email}\n\n*Login Credentials:*\n*Username:* ${client.gstProfile?.username}\n*Password:* ${client.gstProfile?.password}\n\n*Personnel:*\n${stakeholders}`;
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-auto">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-3 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap w-[50px]">S.No.</th>
                <th className="px-3 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 w-[160px]">Trade Name</th>
